rules.css:
width: 26px; height: 26px; overflow: hidden; transition: transform 0.5s var(--ease-liquid); --wave-fade: transparent 10%, rgb(0 0 0 / 0.04) 15%, rgb(0 0 0 / 0.16) 20%, rgb(0 0 0 / 0.42) 25%,
    rgb(0 0 0 / 0.75) 30%, #000 36%, #000 64%, rgb(0 0 0 / 0.75) 70%, rgb(0 0 0 / 0.42) 75%,
    rgb(0 0 0 / 0.16) 80%, rgb(0 0 0 / 0.04) 85%, transparent 90%; mask-image: linear-gradient(90deg, var(--wave-fade));

keyframes.css:
@keyframes grain { 
  0% { transform: translate(0px, 0px); }
  17% { transform: translate(-3%, 2%); }
  33% { transform: translate(2%, -4%); }
  50% { transform: translate(-4%, -1%); }
  67% { transform: translate(3%, 3%); }
  83% { transform: translate(-1%, 4%); }
  100% { transform: translate(1%, -2%); }
}
